# Generated by packaging/brew/formula.sh in masshirodev/ranma on each release.
# Change it there: this file is overwritten.
class Ranma < Formula
  desc "Tiling window manager for the terminal, where every window is a PTY"
  homepage "https://github.com/masshirodev/ranma"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    on_intel do
      url "https://github.com/masshirodev/ranma/releases/download/v0.4.0/ranma-0.4.0-x86_64-apple-darwin.tar.gz"
      sha256 "4b160c16e43664b4e0fe5573b82f86f6eb0464014aa64722678e3aaf89cc94a6"
    end
    on_arm do
      url "https://github.com/masshirodev/ranma/releases/download/v0.4.0/ranma-0.4.0-aarch64-apple-darwin.tar.gz"
      sha256 "4e42d425899d59013a79a3c322e1408201f1a9c230a3c60957c6a7952a30a86b"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/masshirodev/ranma/releases/download/v0.4.0/ranma-0.4.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "ca0cca5d05dbf7ccf61b6e736fd9250d2920607d8cfbcae6cc393c2753d4fabd"
    end
    on_arm do
      url "https://github.com/masshirodev/ranma/releases/download/v0.4.0/ranma-0.4.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "06e8ae6ac1578b4d8db0711019ae14aa39d0c90745883bd8194d5057183d999e"
    end
  end

  def install
    bin.install "ranma"
    man1.install Dir["man/man1/*"]
    man5.install Dir["man/man5/*"]
    man7.install Dir["man/man7/*"]
  end

  def caveats
    <<~EOS
      After an upgrade, check your config against the new build, then move
      running servers onto it (shells and scrollback stay):
        ranma --check-config && ranma upgrade --all
      If the check fails, a terminal that starts ranma falls back to a plain
      shell until the config is fixed.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/ranma --version")
    system bin/"ranma", "--check-config"
  end
end
